def binary_search(xs, target):
    """Return an index of target in sorted list xs, or -1 if absent."""
    low = 0
    high = len(xs) - 1
    while low <= high:
        mid = (low + high) // 2
        if xs[mid] < target:
            low = mid + 1
        elif xs[mid] > target:
            high = mid - 1
        else:
            # To comply with the project decision: "With duplicates, return the last matching index"
            # We continue searching to the right to find the last occurrence.
            last_found = mid
            low = mid + 1
            # We need a way to break or return the last_found once the loop ends.
            # Let's refine the loop to track the last seen index.
            return _binary_search_last(xs, target, low, high, last_found)
    return -1

def _binary_search_last(xs, target, low, high, last_found):
    """Helper to find the last occurrence of target."""
    while low <= high:
        mid = (low + high) // 2
        if xs[mid] < target:
            low = mid + 1
        elif xs[mid] > target:
            high = mid - 1
        else:
            last_found = mid
            low = mid + 1
    return last_found

# Refactored for cleanliness while respecting the "last matching index" rule.
def binary_search(xs, target):
    """Return the last index of target in sorted list xs, or -1 if absent."""
    low = 0
    high = len(xs) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if xs[mid] == target:
            result = mid
            low = mid + 1  # Keep searching right for the last occurrence
        elif xs[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return result
